<?php /** @var array $x */ $c = $x['c']; $r = $x['r']; require __DIR__ . '/_tabs.php'; require __DIR__ . '/_summary.php'; $edit = can('icaap.manage') && !$locked;
$grid = []; foreach ($x['stress'] as $s) { $grid[$s['scenario']][(int)$s['year_no']] = $s; } $a = fn($v) => $v === null ? '' : \App\Core\Money::plain($v);
$zc = ['target' => 'ok', 'warning' => 'warn', 'trigger' => 'danger', 'below_min' => 'danger']; ?>
<form method="post" action="<?= e(url('icaap/' . $c['id'] . '/stress')) ?>" novalidate><?= csrf_field() ?>
<section class="card"><h2><?= e(t('icaap.stress')) ?></h2><p class="muted"><?= e(t('icaap.stress_hint')) ?></p>
<div class="table-wrap"><table class="data icaap-grid"><thead><tr><th><?= e(t('icaap.scenario')) ?></th><th><?= e(t('icaap.year_no')) ?></th><th><?= e(t('icaap.profit')) ?></th><th><?= e(t('icaap.distributions')) ?></th><th><?= e(t('icaap.extra_provisions')) ?></th><th><?= e(t('icaap.rwa_growth')) ?> %</th><th class="num"><?= e(t('icaap.capital')) ?></th><th class="num"><?= e(t('icaap.rwa')) ?></th><th class="num"><?= e(t('icaap.car')) ?></th><th><?= e(t('icaap.zone')) ?></th></tr></thead><tbody>
<?php foreach (\App\Support\Icaap::SCENARIOS as $sc): for ($y = 1; $y <= 3; $y++): $s = $grid[$sc][$y] ?? []; $pth = $r['path'][$sc][$y]; ?><tr>
<?php if ($y === 1): ?><th rowspan="3"><?= e(t('enum.icsc.' . $sc)) ?><br><span class="muted small"><?= e(t('icaap.min_ratio')) ?>: <?= $r['min'][$sc] === null ? '—' : e(number_format($r['min'][$sc] * 100, 2)) . '%' ?></span></th><?php endif; ?><td><?= $y ?></td>
<?php foreach (['profit', 'distributions', 'extra_provisions'] as $f): ?><td><input type="text" name="<?= $f ?>[<?= $sc ?>][<?= $y ?>]" value="<?= e($a($s[$f] ?? null)) ?>" dir="ltr" inputmode="decimal" aria-label="<?= e(t('icaap.' . $f)) ?>"<?= $edit ? '' : ' readonly' ?>><?= field_error($f . '_' . $sc . '_' . $y) ?></td><?php endforeach; ?>
<td><input type="text" name="rwa_growth[<?= $sc ?>][<?= $y ?>]" value="<?= isset($s['rwa_growth']) && $s['rwa_growth'] !== null ? e(rtrim(rtrim(number_format((float)$s['rwa_growth'] * 100, 4, '.', ''), '0'), '.')) : '' ?>" dir="ltr" inputmode="decimal" aria-label="<?= e(t('icaap.rwa_growth')) ?>"<?= $edit ? '' : ' readonly' ?>></td>
<td class="num"><?= $pth['capital'] === null ? '—' : e(number_format($pth['capital'], 0)) ?></td><td class="num"><?= $pth['rwa'] === null ? '—' : e(number_format($pth['rwa'], 0)) ?></td><td class="num"><?= $pth['ratio'] === null ? '—' : e(number_format($pth['ratio'] * 100, 2)) . '%' ?></td>
<td><?= $pth['zone'] ? '<span class="badge ' . $zc[$pth['zone']] . '">' . e(t('enum.iczone.' . $pth['zone'])) . '</span>' : '—' ?></td></tr><?php endfor; endforeach; ?></tbody></table></div></section>
<section class="card"><h2><?= e(t('icaap.scenario_descriptions')) ?></h2><div class="form-grid">
<?php foreach (['s9_base', 's9_moderate', 's9_severe', 's9_specific', 's9_reverse'] as $k): ?><?= ff('textarea', $k, 'icaap.' . $k, $c['narr'][$k] ?? '', ['wide' => true, 'extra' => $edit ? '' : ' readonly']) ?><?php endforeach; ?></div>
<?php if ($edit): ?><div class="actions"><button class="btn" type="submit"><?= e(t('common.save')) ?></button></div><?php endif; ?></section></form>
